import FileSystem from "node:fs";
import Path from "node:path";

// Deterministic reruns: the persistent subhome keeps its configured
// profile, but the ledgers are reset per run (they are the test
// profile's own logs - the suites assert activation lines and the
// exercised flow lines against a known-fresh trail) and the exercise
// work areas are stripped to their seeds (the four registry.json
// files; everything else - the probe manifest, the folded manifests,
// the normalized fixtures, the done markers - is regenerated by each
// run's boots, so stale artifacts cannot flip a check).
export default (Scratch) => {
	FileSystem.rmSync(Path.join(Scratch, "ledgers"), { recursive: true, force: true });
	FileSystem.mkdirSync(Path.join(Scratch, "ledgers"), { recursive: true });
	FileSystem.rmSync(Path.join(Scratch, "nf-work"), { recursive: true, force: true });
	const Work = Path.join(Scratch, "exercise-work");
	if (FileSystem.existsSync(Work)) {
		for (const Entry of FileSystem.readdirSync(Work, { withFileTypes: true })) {
			const Sub = Path.join(Work, Entry.name);
			if (Entry.isDirectory()) {
				for (const File of FileSystem.readdirSync(Sub)) {
					if (File !== "registry.json")
						FileSystem.rmSync(Path.join(Sub, File), {
							force: true,
							recursive: true,
						});
				}
			} else {
				FileSystem.rmSync(Sub, { force: true });
			}
		}
	}
};
